/// Crash recovery for the disposable-account trial.
///
/// A process can die before the normal `finally` cleanup learns what happened.
/// This opt-in pass lists Workers once, then deletes ONLY names generated by
/// this tool. It is never enabled by default and is not production API code.
library;

import 'trial_http.dart';
import 'trial_report.dart';

/// Removes leftover Workers from an interrupted trial.
abstract final class PreviousTrialCleanup {
  static final RegExp _ownedName = RegExp(
    r'^pitak-trial-(?:large-)?[0-9a-f]{8}$',
  );

  /// True only for the two exact random-name shapes generated by the trial.
  static bool ownsWorkerName(String name) => _ownedName.hasMatch(name);

  /// Lists, deletes and verifies previous trial Workers, failing closed.
  static Future<bool> run({
    required TrialHttp api,
    required String accountId,
    required TrialReport report,
  }) async {
    final response = await api.send(
      method: 'GET',
      path: '/accounts/$accountId/workers/scripts',
      retry: true,
    );
    final entries = response.resultList;
    if (!response.ok || !(response.success ?? false) || entries == null) {
      report.check(
        'T0c',
        'previous trial cleanup',
        pass: false,
        detail: 'list ${response.label}',
      );
      return false;
    }

    final names = <String>{};
    var malformed = 0;
    for (final entry in entries) {
      if (entry is! Map || entry['id'] is! String) {
        malformed++;
        continue;
      }
      final name = entry['id'] as String;
      if (ownsWorkerName(name)) names.add(name);
    }
    if (malformed != 0) {
      // An unidentifiable entry must not be mistaken for proof that cleanup is
      // complete. No names are printed, and no deletion is attempted.
      report.check(
        'T0c',
        'previous trial cleanup',
        pass: false,
        detail: 'malformed=$malformed',
      );
      return false;
    }

    var absent = 0;
    for (final name in names) {
      final path = '/accounts/$accountId/workers/scripts/$name';
      await api.send(method: 'DELETE', path: path);
      final read = await api.send(method: 'GET', path: path, retry: true);
      if (read.status == 404) absent++;
    }
    final pass = absent == names.length;
    report.check(
      'T0c',
      'previous trial cleanup',
      pass: pass,
      detail: 'workers=${names.length} absent=$absent',
    );
    return pass;
  }
}
